          "reason": "“公民”与证据 wn31:n:09943131 的“native or naturalized member of a state or political community”一致。",
          "evidence_ids": ["wn31:n:09943131"]
        },
        {
          "sid": "s002",
          "relation": "语义等价",
          "reason": "“国民”同样为国家/政治共同体成员，证据一致。",
          "evidence_ids": ["wn31:n:09943131"]
        },
        {
          "sid": "s003",
          "relation": "范围收窄",
          "reason": "“市民”在扩展组中保留，但所配证据仅政治共同体成员，注释又排除所有居民；一般城市居民义未覆盖且无证据，范围被收窄。",
          "evidence_ids": ["wn31:n:09943131"]
        }
      ],
      "confirmed_within_supplied_evidence": [
        {
          "severity": "Minor",
          "kind": "range_narrowing",
          "source_ids": ["s003"],
          "group_ids": ["SG25-6e5f6170d4e1:extended:1"],
          "evidence_ids": ["wn31:n:09943131"],
          "reason": "源文“市民”通常指城市居民，而政治共同体成员证据仅覆盖国家/政治共同体公民，注释明确“不能等同所有居民”，使一般城市居民义被排除且无证据支持。",
          "counterexample": "普通城市居民未必是政治共同体成员，但中文“市民”常可指一般居民。",
          "repair_suggestion": "为“市民”补充城市居民/市民义证据；若源义确为城市政治成员，应明确标注并暂存一般城市居民义。"
        }
      ],
      "unresolved": [
        "原文未给“市民”语境，无法确定是否仅指城市政治成员；是否需要保留一般居民义待核。"
      ],
      "preferences": [],
      "note": "核心公民/国民证据充分；扩展“市民”证据不匹配，需补证据或界定范围。"
    },
    {
      "id": "SG25-6b15713240e8",
      "scope_checks": [
        {
          "sid": "s001",
          "relation": "无法确定",
          "reason": "“教化”被 held 暂存；供应证据 n:04819244（修养品质）与 n:13470143（社会文明化过程）均不能无歧义对应裸译“教化”，个人训导/社会过程待核。",
          "evidence_ids": ["wn31:n:04819244", "wn31:n:13470143"]
        },
        {
          "sid": "s002",
          "relation": "语义等价",
          "reason": "核心组“文明”以 n:08128749 社会发展状态义覆盖原文文明的一个主要用法；无证据表明该源义更广且未被其他层覆盖。",
          "evidence_ids": ["wn31:n:08128749"]
        },
        {
          "sid": "s003",
          "relation": "范围收窄",
          "reason": "核心组“文明社会”链接 n:08304765 特定社会/文明，证据仅指特定时空的具体社会；一般“文明社会/发达社会”义未覆盖，且 n:08128749 已存在可用于该义。",
          "evidence_ids": ["wn31:n:08304765"]
        }
      ],
      "confirmed_within_supplied_evidence": [
        {
          "severity": "Minor",
          "kind": "range_narrowing",
          "source_ids": ["s003"],
          "group_ids": ["SG25-6b15713240e8:core:2"],
          "evidence_ids": ["wn31:n:08304765"],
          "reason": "“文明社会”通常指发达/有文明的社会，而 n:08304765 定义为“a particular society at a particular time and place”，仅覆盖特定文明/社会，一般义未在候选层保留。",
          "counterexample": "早期玛雅文明是特定文明，不等于一般“文明社会”。",
          "repair_suggestion": "将“文明社会”链接到 n:08128749（发达社会义），或将 n:08304765 明确标为“特定文明”，并区分两个义项。"
        }
      ],
      "unresolved": [
        "s001“教化”待核：需澄清是个人教养/训导还是社会文明化过程；当前 held 未覆盖。",
        "s002“文明”可能还包含文化/修养义，但该义项未在任何层级明确保留；证据 n:04819244 存在但未采用。"
      ],
      "preferences": [],
      "note": "核心“文明”与“文明社会”存在“发展状态 vs 特定社会”的区分，但“文明社会”所配证据偏窄；s001已显式暂存。"
    }
  ]
